        }
      }
    } catch (err) {
      const errorEvent = this._log.append({
        worker: handle.id,
        harness,
        turnEpoch: this._safeTurnEpoch(handle),
        kind: 'error',
        actor: 'policy',
        payload: { message: String((err && err.message) || err), phase: 'trust_gate', trustPhase },
