          const evidence = this._coordMapEvent(errorEvent);
          const transitioned = this._coordination.transitionTask(task.id, 'failed', durable.version, {
            actor: 'policy', key: `task.failed:${task.id}:trust_gate:${errorEvent.seq}`,
