export class EffortSelectionError extends Error {
  constructor(message, code = 'effort_unavailable') {
    super(message);
    this.name = 'EffortSelectionError';
    this.code = code;
  }
}

export function normalizeEffort(effort, policy) {
  if (effort !== undefined && (typeof effort !== 'string' || effort.length === 0)) {
    throw new EffortSelectionError('effort must be a non-empty exact identifier', 'invalid_effort');
  }
  const compatible = policy?.reasoningEffort;
  if (effort !== undefined && compatible !== undefined && effort !== compatible) {
    throw new EffortSelectionError('effort conflicts with modelPolicy.reasoningEffort', 'effort_policy_conflict');
  }
  return effort ?? compatible ?? null;
}

export function resolveCardEffort(card, requested) {
  const inventory = card?.modelSelection?.reasoningEffort;
  if (requested != null && (!Array.isArray(inventory) || !inventory.includes(requested))) {
    return { ok: false, reason: 'reasoning_effort_unsupported' };
  }
  return { ok: true, effort: requested ?? card?.modelSelection?.configuredEffort ?? null };
}

// JSON is deliberately used rather than separator concatenation: every string is length-safe.
export function routeTupleKey(card, model, effort, taskType = 'general') {
