    card?.harness ?? 'unknown', card?.version ?? 'unknown',
    model ?? card?.modelSelection?.configuredDefault ?? 'default',
    effort ?? card?.modelSelection?.configuredEffort ?? 'default',
    card?.modelSelection?.family ?? 'default', taskType,
